)
public class ComunicazioneFinderImpl extends ComunicazioneFinderBaseImpl implements ComunicazioneFinder {
   @Reference
   private UserLocalService userLocalService;

   @Reference
   private OldUserResolver oldUserResolver;

   public List<Comunicazione> findByRichiestaId(long richiestaId, int start, int end, OrderByComparator<Comunicazione> orderByComparator) {
      return this.comunicazionePersistence.findByRichiestaId(richiestaId, start, end, orderByComparator);
