      return this.comunicazionePersistence.findByDomandaBandoId(domandaBandoId, start, end, orderByComparator);
   }

   public int countByDomandaBandoId(long domandaBandoId) {
      return this.comunicazionePersistence.countByDomandaBandoId(domandaBandoId);
   }

   public List<Comunicazione> findNotInviateAndNotInterna() {
      DynamicQuery dq = DynamicQueryFactoryUtil.forClass(Comunicazione.class, this.getClass().getClassLoader());
      dq.add(RestrictionsFactoryUtil.isNull("dataInvio"));
      return this.comunicazionePersistence.findWithDynamicQuery(dq);
   }

   public List<Comunicazione> findByFilters(ComunicazioneFilters filters, int start, int end) {
      List<Comunicazione> retVal = null;
      DynamicQuery dynamicQuery = this.generaQuery(filters);
      if (!Validator.isBlank(filters.getOrderByCol())) {
         boolean direzione = true;
         String orderByType = filters.getOrderByType();
         if ("desc".equalsIgnoreCase(orderByType)) {
            direzione = false;
         }

         String orderByCol = filters.getOrderByCol();
         if ("tipologia".equalsIgnoreCase(orderByCol)) {
            orderByCol = "tipologiaComunicazioneId";
         }

         OrderByComparator<Comunicazione> comparator = OrderByComparatorFactoryUtil.create("Comunicazione", new Object[]{orderByCol, direzione});
         retVal = this.comunicazionePersistence.findWithDynamicQuery(dynamicQuery, start, end, comparator);
      } else {
         retVal = this.comunicazionePersistence.findWithDynamicQuery(dynamicQuery, start, end);
      }

      return retVal;
   }

   public int countByFilters(ComunicazioneFilters filters) {
      DynamicQuery dynamicQuery = this.generaQuery(filters);
      return (int)this.comunicazionePersistence.countWithDynamicQuery(dynamicQuery);
   }

   private DynamicQuery generaQuery(ComunicazioneFilters filters) {
      DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(Comunicazione.class, this.getClass().getClassLoader());

      if(filters.getGroupId()>0) {
          dynamicQuery.add(RestrictionsFactoryUtil.eq("groupId", filters.getGroupId()));
      }

      if(filters.getCompanyId()>0) {
          dynamicQuery.add(RestrictionsFactoryUtil.eq("companyId", filters.getCompanyId()));
      }

      if(filters.getRichiestaId()>0){
          dynamicQuery.add(RestrictionsFactoryUtil.eq("richiestaId", filters.getRichiestaId()));
      }

      if (filters.getDataInvioDa() != null) {
         dynamicQuery.add(RestrictionsFactoryUtil.gt("dataInvio", filters.getDataInvioDa()));
      }

      if (filters.getDataInvioA() != null) {
         dynamicQuery.add(RestrictionsFactoryUtil.lt("dataInvio", filters.getDataInvioA()));
      }

      if (filters.getOrganizzazione() != null) {
         dynamicQuery.add(RestrictionsFactoryUtil.eq("destinatarioOrganizationId", filters.getOrganizzazione()));
      }

      if (filters.getTipologia() != null) {
         dynamicQuery.add(RestrictionsFactoryUtil.eq("tipologiaComunicazioneId", filters.getTipologia()));
      }

      if (filters.getTitoloDescrizione() != null) {
         String val = "%" + filters.getTitoloDescrizione() + "%";
         dynamicQuery.add(RestrictionsFactoryUtil.ilike("titolo", val));
      }

      if (Validator.isNotNull(filters.getUsername())) {

    	  DynamicQuery userQuery = UserLocalServiceUtil.dynamicQuery();
    	  String val = "%" + filters.getUsername() + "%";

    	  Disjunction disjunctionQuery = RestrictionsFactoryUtil.disjunction();
    	  disjunctionQuery.add(RestrictionsFactoryUtil.ilike("firstName", val));
    	  disjunctionQuery.add(RestrictionsFactoryUtil.ilike("lastName", val));
    	  disjunctionQuery.add(RestrictionsFactoryUtil.ilike("screenName", val));

    	  userQuery.add(disjunctionQuery);
    	  userQuery.setProjection(ProjectionFactoryUtil.property("userId"));

    	  List<Long> userIds = UserLocalServiceUtil.dynamicQuery(userQuery);


    	  DynamicQuery destinatarioComunicazioneQuery = DestinatarioComunicazioneLocalServiceUtil.dynamicQuery();
    	  destinatarioComunicazioneQuery.add(PropertyFactoryUtil.forName("primaryKey.destinatarioId").in(userIds));
    	  destinatarioComunicazioneQuery.setProjection(ProjectionFactoryUtil.property("primaryKey.comunicazioneId"));

    	  List<Long> comuIds = DestinatarioComunicazioneLocalServiceUtil.dynamicQuery(destinatarioComunicazioneQuery);

    	  Criterion criterion = PropertyFactoryUtil.forName("comunicazioneId").in(comuIds);

          dynamicQuery.add(criterion);

       }

      if (Validator.isNotNull(filters.getDestinatarioId())) {
    	//SELECT primaryKey.comunicazioneId FROM DestinatarioComunicazione WHERE primaryKey.destinatarioId IN (destinatarioId [, oldUserId])
         List<Long> destinatariIds = new ArrayList<>();
         destinatariIds.add(filters.getDestinatarioId());

         // Continuità operativa migrazione SPID: se il destinatario è un operatore migrato
         // (old_screen_name valorizzato), include anche le comunicazioni indirizzate al vecchio userId.
         // Per i destinatari non migrati getOldUserId restituisce null: nessuna regressione.
         Long oldDestinatarioId = oldUserResolver.getOldUserId(filters.getDestinatarioId());
         if (oldDestinatarioId != null) {
            destinatariIds.add(oldDestinatarioId);
         }

         DynamicQuery destinatarioComunicazioneQuery = DestinatarioComunicazioneLocalServiceUtil.dynamicQuery();
         destinatarioComunicazioneQuery.add(PropertyFactoryUtil.forName("primaryKey.destinatarioId").in(destinatariIds));
         destinatarioComunicazioneQuery.setProjection(ProjectionFactoryUtil.property("primaryKey.comunicazioneId"));
         Criterion criterion = PropertyFactoryUtil.forName("comunicazioneId").in(destinatarioComunicazioneQuery);
         dynamicQuery.add(criterion);
      }

      if (Validator.isNotNull(filters.getOrganizzazioniIDs()) && !filters.getOrganizzazioniIDs().isEmpty()) {
         Criterion criterion = PropertyFactoryUtil.forName("subOrganizationId").in(filters.getOrganizzazioniIDs());
         dynamicQuery.add(criterion);
      }


      if (filters.getStato() != null) {

    	DynamicQuery letturaQuery = LetturaMessaggioLocalServiceUtil.dynamicQuery();
		letturaQuery.add(RestrictionsFactoryUtil.eq("primaryKey.userId", filters.getUserId()));
		letturaQuery.add(RestrictionsFactoryUtil.isNotNull("dataLettura"));
		letturaQuery.setProjection(ProjectionFactoryUtil.property("primaryKey.messaggioId"));



		DynamicQuery messaggioQuery = MessaggioLocalServiceUtil.dynamicQuery();
		//where messaggioId not in
		Criterion letturaCriterion = PropertyFactoryUtil.forName("messaggioId").in(letturaQuery);
		messaggioQuery.add(RestrictionsFactoryUtil.not(letturaCriterion));
		//select comunicazioneId
		ProjectionList projectionList = ProjectionFactoryUtil.projectionList();
		projectionList.add(ProjectionFactoryUtil.groupProperty("comunicazioneId"));
		//groupBy comunicazioneId
		//projectionList.add(ProjectionFactoryUtil.property("comunicazioneId"));
		messaggioQuery.setProjection(projectionList);
		//messaggioQuery.setProjection(ProjectionFactoryUtil.property("comunicazioneId"));

		Criterion comunicazioneCriterion = PropertyFactoryUtil.forName("comunicazioneId").in(messaggioQuery);

		if (!filters.getStato()) {
			dynamicQuery.add(comunicazioneCriterion);
		} else {
			dynamicQuery.add(RestrictionsFactoryUtil.not(comunicazioneCriterion));
		}
	}

      return dynamicQuery;
   }

   private List<Long> searchUsers(String query) {
      String pattern = "%" + query + "%";
      DynamicQuery dq = DynamicQueryFactoryUtil.forClass(User.class, this.getClass().getClassLoader());
      Criterion cfClause = RestrictionsFactoryUtil.ilike("screenName", pattern);
      Criterion fnClause = RestrictionsFactoryUtil.ilike("firstName", pattern);
      Criterion lnClause = RestrictionsFactoryUtil.ilike("lastName", pattern);
      Criterion nameClause = RestrictionsFactoryUtil.or(fnClause, lnClause);
      dq.add(RestrictionsFactoryUtil.or(nameClause, cfClause));
      dq.setProjection(ProjectionFactoryUtil.property("userId"));
      List<Long> ids = new ArrayList(this.userLocalService.dynamicQuery(dq));
      ids.add(0L);
      return ids;
   }

   public List<Comunicazione> findComunicazioniNonLetteByUserId(Long userId) {
		DynamicQuery letturaMessaggioQuery = LetturaMessaggioLocalServiceUtil.dynamicQuery();
		letturaMessaggioQuery.add(RestrictionsFactoryUtil.eq("primaryKey.userId", userId));
		letturaMessaggioQuery.add(RestrictionsFactoryUtil.isNotNull("dataLettura"));
		letturaMessaggioQuery.setProjection(ProjectionFactoryUtil.property("primaryKey.messaggioId"));

		DynamicQuery messaggioQuery = MessaggioLocalServiceUtil.dynamicQuery();
		Criterion letturaCriterion =  PropertyFactoryUtil.forName("messaggioId").notIn(letturaMessaggioQuery);
		messaggioQuery.add(letturaCriterion);
		messaggioQuery.add(PropertyFactoryUtil.forName("userId").ne(userId));
		messaggioQuery.setProjection(ProjectionFactoryUtil.property("comunicazioneId"));

	    DynamicQuery dynamicQuery = ComunicazioneLocalServiceUtil.dynamicQuery();
	    Criterion comunicazioneCriterion = PropertyFactoryUtil.forName("comunicazioneId").in(messaggioQuery);
	    dynamicQuery.add(comunicazioneCriterion);
	    return comunicazionePersistence.findWithDynamicQuery(dynamicQuery);
   }

