package it.servizidigitali.gestionecomunicazioni.service.impl;

import com.liferay.portal.aop.AopService;
import com.liferay.portal.kernel.exception.PortalException;
import com.liferay.portal.kernel.model.User;
import com.liferay.portal.kernel.service.ServiceContext;

import java.util.List;

import it.servizidigitali.gestionecomunicazioni.model.DestinatarioComunicazione;
import it.servizidigitali.gestionecomunicazioni.service.base.DestinatarioComunicazioneLocalServiceBaseImpl;
import it.servizidigitali.gestionecomunicazioni.service.persistence.DestinatarioComunicazionePK;

import org.osgi.service.component.annotations.Component;

/**
 * @author Brian Wing Shun Chan
 */
@Component(
	property = "model.class.name=it.servizidigitali.gestionecomunicazioni.model.DestinatarioComunicazione",
	service = AopService.class
)
public class DestinatarioComunicazioneLocalServiceImpl
	extends DestinatarioComunicazioneLocalServiceBaseImpl {

	@Override
	public void addDestinatarioComunicazione(ServiceContext serviceContext, long comunicazioneId, List<Long> utentiDestinatariId) throws PortalException {

		for(Long utenteDestinatrarioId : utentiDestinatariId) {
			DestinatarioComunicazionePK destinatarioComunicazionePK = new DestinatarioComunicazionePK(comunicazioneId, utenteDestinatrarioId);

			DestinatarioComunicazione model = destinatarioComunicazionePersistence.create(destinatarioComunicazionePK);

			model.setGroupId(serviceContext.getScopeGroupId());
			model.setCompanyId(serviceContext.getCompanyId());
			model.setUserId(serviceContext.getUserId());

			if(serviceContext.getUserId() > 0) {
				User user = userLocalService.getUser(serviceContext.getUserId());
				model.setUserName(user.getFullName());
			}

			destinatarioComunicazionePersistence.update(model);
		}


	}

	public List<DestinatarioComunicazione> findByComunicazioneId (long comunicazioneId) {

		return destinatarioComunicazionePersistence.findByComunicazioneId(comunicazioneId);
	}

	public List<DestinatarioComunicazione> findByDestinatarioId (long destinatarioId){

		return destinatarioComunicazionePersistence.findByDestinatarioId(destinatarioId);
	}


}

