/**
 * @author pindi
 *
 */
@Component(immediate = true, name = "communicationService", service = CommunicationService.class, configurationPid = "it.servizidigitali.communication.configuration.TemplateComunicazioniEnteConfiguration")
public class CommunicationServiceImpl implements CommunicationService {

	private static final String USER_FULL_NAME_POSIZIONALE = "user_full_name";
	private static final String NUOVO_STATO_RICHIESTA_POSIZIONALE = "nuovo_stato_richiesta";
	private static final String VECCHIO_STATO_RICHIESTA_POSIZIONALE = "vecchio_stato_richiesta";
	private static final String RICHIESTA_ID_POSIZIONALE = "richiesta_id";
	private static final String OGGETTO_RICHIESTA_POSIZIONALE = "oggetto_richiesta";
	private static final String NOME_ENTE_POSIZIONALE = "nome_ente";
	private static final String URL_POSIZIONALE = "url"; 
	private static final String MINUTI_POSIZIONALE = "minuti";
	private static final String STATO_RICHIESTA_POSIZIONALE = "stato_richiesta";
	private static final String ESITO = "esito";
	private static final String NOTE = "note";
	private static final String NOME_BANDO = "nome_bando";
	private static final String NOME_SERVIZIO = "nome_servizio";
	private static final String DOMANDA_BANDO_ID_POSIZIONALE = "domanda_bando_id";
	private static final String OGGETTO_DOMANDA_POSIZIONALE = "oggetto_domanda";
	private static final String NOME_FORM = "nome_form";
    private static final String NUMERO_PROTOCOLLO_ESTESO = "numero_protocollo_esteso";
    private static final String AREA_TEMATICA = "area_tematica";
    private static final String DESCRIZIONE_BREVE = "descrizione_breve";
    private static final String NUMERO_PROTOCOLLO = "numero_protocollo";
    private static final String DATA_PROTOCOLLO = "data_protocollo";
    private static final String DATA_RICHIESTA = "data_richiesta";
    private static final String RAGIONE_SOCIALE = "note_ragione_sociale";
    private static final String PRESENTATA_DALL_ENTE = " dal soggetto proponente ";



	private static final Log log = LogFactoryUtil.getLog(CommunicationServiceImpl.class.getName());
	public static final String DATA_SCADENZA_POSIZIONALE = "data_scadenza";
	public static final String CODICE_BANDO_POSIZIONALE = "codice_bando";
	public static final String NOME_BANDO_POSIZIONALE = "nome_bando";

	private volatile TemplateComunicazioniEnteConfiguration templateComunicazioniEnteConfiguration;

	private volatile NotificaCambioStatoEnteConfiguration notificaCambioStatoConfiguration;

	private ConfigurationProvider configurationProvider;

	@Reference
	private CommunicationSender communicationSender;

	@Reference
	private UtenteOrganizzazioneCanaleComunicazioneLocalService utenteOrganizzazioneCanaleComunicazioneLocalService;

	@Reference
	private OrganizationUtility organizationUtility;

	@Reference
	private ComunicazioneLocalService comunicazioneLocalService;

	@Reference
	private TipologiaComunicazioneLocalService tipologiaComunicazioneLocalService;

	@Reference
	private CounterLocalService counterLocalService;

	@Reference
	private MessaggioLocalService messaggioLocalService;

	@Reference
	private DestinatarioComunicazioneLocalService destinatarioComunicazioneLocalService;

	@Reference
	private UserLocalService userLocalService;

	@Reference
	private CamundaClient camundaClient;

	@Reference
	private OrganizationLocalService organizationLocalService;

	@Activate
	@Modified
	private void activate(Map<String, Object> props) {
		templateComunicazioniEnteConfiguration = ConfigurableUtil.createConfigurable(TemplateComunicazioniEnteConfiguration.class, props);
		notificaCambioStatoConfiguration = ConfigurableUtil.createConfigurable(NotificaCambioStatoEnteConfiguration.class, props);
	}

	@Reference
	protected void setConfigurationProvider(ConfigurationProvider configurationProvider) {
		this.configurationProvider = configurationProvider;
	}

	@Override
	public void sendCambioStatoRichiestaCommunication(String nomeEnte, long richiestaId, String oggettoRichiesta, String vecchioStato, String nuovoStato, Utente utente, long companyId, long groupId, long servizioId, long organizationId, AccountDto emailAccount)
			throws CommunicationException {

		// Caricamento canali di comunicazione utente da preferenze
		List<Canale> canali = getCanaliComunicazioneUtente(utente, groupId);

		log.debug("Invio comunicazione per cambio stato richiesta - canali comunicazione per " + utente.getCodiceFiscale() + ": " + canali);

		if (canali == null || canali.isEmpty()) {
			return;
		}

		sendCambioStatoRichiestaCommunicationPrivate(nomeEnte, richiestaId, oggettoRichiesta, vecchioStato, nuovoStato, utente, companyId, groupId, canali, servizioId, organizationId, emailAccount);
	}

	@Override
	public void sendCambioStatoDomandaBandoCommunication(String nomeEnte, long domandaBandoId, String oggettoDomandaBando, String stato, Utente utente, long companyId,
														 long groupId, String processInstanceId, boolean checkAbilitaVisualizzazione, String organizationId, String note, String firmatario, AccountDto emailAccount, String ragioneSociale)
			throws CommunicationException {

		// Caricamento canali di comunicazione utente da preferenze
		List<Canale> canali = getCanaliComunicazioneUtente(utente, groupId);

		log.debug("Invio comunicazione per cambio stato domanda bando - canali comunicazione per " + utente.getCodiceFiscale() + ": " + canali);

		if (canali == null || canali.isEmpty()) {
			return;
		}

		sendCambioStatoDomandaBandoCommunicationPrivate(nomeEnte, domandaBandoId, oggettoDomandaBando, stato, utente, companyId, groupId, canali, processInstanceId, checkAbilitaVisualizzazione, organizationId, note, firmatario, emailAccount, ragioneSociale);
	}

	@Override
	public void sendCambioStatoRichiestaCommunication(String nomeEnte, long richiestaId, String oggettoRichiesta, String vecchioStato, String nuovoStato, Utente utente, long companyId, long groupId,
													  List<Canale> canali, long servizioId, long organizationId, AccountDto emailAccount) throws CommunicationException {

		log.debug("Invio comunicazione per cambio stato richiesta - canali comunicazione per " + utente.getCodiceFiscale() + ": " + canali);

		if (canali == null || canali.isEmpty()) {
			throw new CommunicationException("Nessun canale di invio specificato.");
		}
		sendCambioStatoRichiestaCommunicationPrivate(nomeEnte, richiestaId, oggettoRichiesta, vecchioStato, nuovoStato, utente, companyId, groupId, canali, servizioId, organizationId, emailAccount);
	}

	@Override

	public void sendNotificaIntegrazioneCompletata(long richiestaId, String oggettoRichiesta, long organizationId, long groupId) {

		try {
			sendNotificaIntegrazioneCompletataPrivate(richiestaId, oggettoRichiesta, organizationId, groupId);
		} catch (CommunicationException e) {

			log.error("::sendNotificaIntegrazioneCompletata "+e.getMessage());
		}
	}

	/**
	 * @param nomeEnte
	 * @param richiestaId
	 * @param oggettoRichiesta
	 * @param vecchioStato
	 * @param nuovoStato
	 * @param utente
	 * @param companyId
	 * @param groupId
	 * @param canali
	 * @param emailAccount
	 * @throws CommunicationException
	 */
	private void sendCambioStatoRichiestaCommunicationPrivate(String nomeEnte, long richiestaId, String oggettoRichiesta, String vecchioStato, String nuovoStato, Utente utente, long companyId,
															  long groupId, List<Canale> canali, long servizioId, long organizationId, AccountDto emailAccount) throws CommunicationException {
		try {
			if (groupId != 0) {
				templateComunicazioniEnteConfiguration = configurationProvider.getGroupConfiguration(TemplateComunicazioniEnteConfiguration.class, groupId);
			}

			String cambioStatoRichiestaEmailSubjectTemplate = templateComunicazioniEnteConfiguration.cambioStatoRichiestaEmailSubjectTemplate();
			String cambioStatoRichiestaEmailBodyTemplate = templateComunicazioniEnteConfiguration.cambioStatoRichiestaEmailBodyTemplate();

			Map<String, String> valuesMap = new HashMap<String, String>();
