	private void sendNotificaIntegrazioneCompletataPrivate(long richiestaId, String oggettoRichiesta, long organizationId, long groupId) throws CommunicationException {

		try {
			if (groupId != 0) {
				templateComunicazioniEnteConfiguration = configurationProvider.getGroupConfiguration(TemplateComunicazioniEnteConfiguration.class, groupId);
			}

			List<User> utentiBackOffice = userLocalService.getOrganizationUsers(organizationId);

			Canale canale = Canale.EMAIL;

			for(User user : utentiBackOffice) {
				Utente utente = new Utente();
				utente.setEmail(user.getEmailAddress());

				String object = templateComunicazioniEnteConfiguration.notificaIntegrazioneInseritaEmailSubjectTemplate();
				String emailtemplate = templateComunicazioniEnteConfiguration.notificaIntegrazioneInseritaEmailBodyTemplate();

				Map<String, String> objectValuesMap = new HashMap<String, String>();
				objectValuesMap.put("richiesta_id", String.valueOf(richiestaId));
