				String oggetto = notificaObjectStringSubstitutor.replace(object);


				Map<String, String> valuesMap = new HashMap<String, String>();
				valuesMap.put("richiesta_id", String.valueOf(richiestaId));
				valuesMap.put("oggetto_richiesta", oggettoRichiesta);
				valuesMap.put(USER_FULL_NAME_POSIZIONALE, user.getFirstName() + " " +user.getLastName());

				StringSubstitutor notificaConfigStringSubstitutor = new StringSubstitutor(valuesMap);
				String messaggioContenuto = notificaConfigStringSubstitutor.replace(emailtemplate);

				if(Validator.isNotNull(messaggioContenuto)) {
					ComunicazioneDto com = new ComunicazioneDto(oggetto, messaggioContenuto, Collections.singletonList(utente), false, null);
					log.debug("Invio comunicazione tramite canale '" + canale.getName() + "' a '" + user.getScreenName() + "'");
					EsitoComunicazione esito = communicationSender.sendNow(com, canale);

					String messageId = esito.getMessageId();
					log.debug("Comunicazione inviata a '" + user.getScreenName() + "' inviata. MessageID: " + messageId);

				}
			}
		}
		catch(ConfigurationException e) {
			log.error("sendNotificaIntegrazioneCompletataPrivate :: " + e.getMessage(), e);
		}

	}

