			valuesMap.put(NOME_FORM, form);
			valuesMap.put(RAGIONE_SOCIALE, Validator.isNotNull(ragioneSociale) ? PRESENTATA_DALL_ENTE + ragioneSociale : StringPool.BLANK);


			StringSubstitutor invioNuovaNotificaApprovazioneBodyTemplateStringSubstitutor = new StringSubstitutor(valuesMap);
			String invioNuovaNotificaApprovazioneBodyTemplateResolved = invioNuovaNotificaApprovazioneBodyTemplateStringSubstitutor.replace(invioNotificaBodyTemplate);

			List<Utente> utenti = Arrays.asList(utente);

			ComunicazioneDto comunicazione = new ComunicazioneDto(invioNuovaNotificaApprovazioneSubjectTemplateResolved, invioNuovaNotificaApprovazioneBodyTemplateResolved, utenti, null, false, null,
					companyId, groupId);
			comunicazione.setAccount(emailAccount);

			for (Canale canale : canali) {
				EsitoComunicazione esitoComunicazione = communicationSender.send(comunicazione, canale);
				if (Validator.isNotNull(esitoComunicazione.getError())) {
					throw new CommunicationException("Errore durante l'invio della comunicazione tramite canale : " + canale.getName() + ", errore: " + esitoComunicazione.getError());
				}
			}

			creaComunicazioneDomandaBando(domandaBandoId, utente, invioNuovaNotificaApprovazioneSubjectTemplateResolved, invioNuovaNotificaApprovazioneBodyTemplateResolved, groupId, companyId);

		}
		catch (ConfigurationException e) {
			log.error("sendNuovaDomandaBandoCommunicationPrivate :: " + e.getMessage(), e);
		}

	}

	/**
	 * @param utente
	 * @param groupId
	 * @return
	 * @throws CommunicationException
	 */
	private List<Canale> getCanaliComunicazioneUtente(Utente utente, long groupId) throws CommunicationException {
		List<Canale> canali = null;
		try {
			Organization siteOrganization = organizationUtility.getSiteOrganization(groupId);
			List<UtenteOrganizzazioneCanaleComunicazione> canaliComunicazioneUtente = utenteOrganizzazioneCanaleComunicazioneLocalService
					.getListaCanaleComunicazioneByUtenteOrganization(utente.getUtenteId(), siteOrganization.getOrganizationId());

			if (canaliComunicazioneUtente != null) {
				canali = new ArrayList<Canale>();
				for (UtenteOrganizzazioneCanaleComunicazione utenteOrganizzazioneCanaleComunicazione : canaliComunicazioneUtente) {
					Canale canale = Canale.getSupportedChannel(utenteOrganizzazioneCanaleComunicazione.getCanale().getCodice());
					canali.add(canale);
				}
			}
		}
		catch (PortalException e) {
			log.error("sendCambioStatoRichiestaCommunication :: " + e.getMessage(), e);
			throw new CommunicationException(e);
		}
		return canali;
	}

	@Override
	public void sendVerificaEmailCommunication(String nomeEnte, String urlVerifica, int minutiValidita, Utente utente, long companyId, long groupId) throws CommunicationException {

		try {
			if (groupId != 0) {
				templateComunicazioniEnteConfiguration = configurationProvider.getGroupConfiguration(TemplateComunicazioniEnteConfiguration.class, groupId);
			}

			String invioVerificaEmailSubjectTemplate = templateComunicazioniEnteConfiguration.invioVerificaEmailSubjectTemplate();
			String invioVerificaEmailBodyTemplate = templateComunicazioniEnteConfiguration.invioVerificaEmailBodyTemplate();
			Map<String, String> valuesMap = new HashMap<String, String>();
			valuesMap.put(NOME_ENTE_POSIZIONALE, nomeEnte);

			StringSubstitutor invioVerificaEmailSubjectTemplateStringSubstitutor = new StringSubstitutor(valuesMap);
			String invioVerificaEmailSubjectTemplateResolved = invioVerificaEmailSubjectTemplateStringSubstitutor.replace(invioVerificaEmailSubjectTemplate);

			valuesMap = new HashMap<String, String>();
			valuesMap.put(USER_FULL_NAME_POSIZIONALE, utente.getNome() + StringPool.SPACE + utente.getCognome());
			valuesMap.put(URL_POSIZIONALE, urlVerifica);
			valuesMap.put(MINUTI_POSIZIONALE, String.valueOf(minutiValidita));

			StringSubstitutor invioVerificaEmailBodyTemplateStringSubstitutor = new StringSubstitutor(valuesMap);
			String invioVerificaEmailBodyTemplateResolved = invioVerificaEmailBodyTemplateStringSubstitutor.replace(invioVerificaEmailBodyTemplate);

			List<Utente> utenti = Arrays.asList(utente);

			ComunicazioneDto comunicazione = new ComunicazioneDto(invioVerificaEmailSubjectTemplateResolved, invioVerificaEmailBodyTemplateResolved, utenti, null, false, null, companyId, groupId);

			// Invio email
			EsitoComunicazione esitoComunicazione = communicationSender.sendNow(comunicazione, Canale.EMAIL);

			if (Validator.isNotNull(esitoComunicazione.getError())) {
				throw new CommunicationException("Errore durante l'invio della comunicazione tramite canale : " + Canale.EMAIL + ", errore: " + esitoComunicazione.getError());
			}
		}
		catch (Exception e) {
			log.error("sendVerificaEmailCommunication :: " + e.getMessage(), e);
		}

	}



    private Comunicazione creaComunicazioneDomandaBando(long domandaBandoId, Utente utente, String titolo, String descrizione, long groupId, long companyId) {
        Comunicazione model = comunicazioneLocalService.createComunicazione(counterLocalService.increment());
        TipologiaComunicazione tipologia = tipologiaComunicazioneLocalService.getTipologiaByNome(TipologiaComunicazioniEnum.Comunicazione.name());

        model.setCodiceServizio(null);
        model.setDomandaBandoId(domandaBandoId);

        model.setGroupId(groupId);
        model.setCompanyId(companyId);
        model.setOrganizationId(groupId);
        model.setTitolo(titolo.trim());
        model.setDataInizio(new Date());
        model.setDataFine(new Date());
        model.setDataInvio(new Date());
        model.setTipologiaComunicazioneId(tipologia.getTipologiaComunicazioneId());
        model.setDestinatarioOrganizationId(groupId);
        model.setInterna(false);

        comunicazioneLocalService.updateComunicazione(model);
        creaMessaggioComunicazione(utente.getUtenteId(), groupId, companyId, model.getComunicazioneId(), descrizione);

        return model;

    }



    private Comunicazione creaComunicazioneRichiestaCambioReferente(long richiestaReferenteIstanzaId, Utente utente, String titolo, String descrizione, long groupId, long companyId) {
        Comunicazione model = comunicazioneLocalService.createComunicazione(counterLocalService.increment());
        TipologiaComunicazione tipologia = tipologiaComunicazioneLocalService.getTipologiaByNome(TipologiaComunicazioniEnum.Comunicazione.name());

        model.setCodiceServizio(null);
        model.setRichiestaReferenteIstanzaId(richiestaReferenteIstanzaId);

        model.setGroupId(groupId);
        model.setCompanyId(companyId);
        model.setOrganizationId(groupId);
        model.setTitolo(titolo.trim());
        model.setDataInizio(new Date());
        model.setDataFine(new Date());
        model.setDataInvio(new Date());
        model.setTipologiaComunicazioneId(tipologia.getTipologiaComunicazioneId());
        model.setDestinatarioOrganizationId(groupId);
        model.setInterna(false);

        comunicazioneLocalService.updateComunicazione(model);
        creaMessaggioComunicazione(utente.getUtenteId(), groupId, companyId, model.getComunicazioneId(), descrizione);

        return model;

    }

	private Messaggio creaMessaggioComunicazione(long userId, long groupId, long companyId, long comunicazioneId, String contenuto) {

		Messaggio messaggio = messaggioLocalService.createMessaggio(counterLocalService.increment());
		messaggio.setComunicazioneId(comunicazioneId);
		messaggio.setContenuto(contenuto);
		messaggio.setCompanyId(companyId);
		messaggio.setGroupId(groupId);

		messaggioLocalService.updateMessaggio(messaggio);
		aggiungiDestinatarioComunicazione(groupId, companyId, comunicazioneId, userId);

		return messaggio;
	}

	private void aggiungiDestinatarioComunicazione(long groupId, long companyId, long comunicazioneId, long destinatarioUserId){
		ServiceContext serviceContext = new ServiceContext();

		serviceContext.setScopeGroupId(groupId);
		serviceContext.setCompanyId(companyId);
		serviceContext.setUserId(0);

		try {
			destinatarioComunicazioneLocalService.addDestinatarioComunicazione(serviceContext, comunicazioneId, new ArrayList<Long>(Arrays.asList(destinatarioUserId)));
		} catch (PortalException e) {
			log.error(e);
		}
	}

