    @Reference
    private MessaggioLocalService messaggioLocalService;

    @Reference
    private OrganizationUtility _organizationUtility;

    @Override
    public Page<ComunicazioneUtenteResponse> getComunicazioniUtente(String userToken, Integer page, Integer size, String nomeComune, String amministrazione, FiltriComunicazioni filtriComunicazioni) throws Exception {
        if ((Validator.isNull(nomeComune) && Validator.isNull(amministrazione)) || (!Validator.isNull(nomeComune) && !Validator.isNull(amministrazione))) {
            throw new BadRequestException("E' obbligatorio compilare solo uno tra i due campi nomeComune e amministrazione");
        }

        Long userId;
        String codiceFiscale;

        try {
            Map<String, Object> claims = _jwtUtilityService.verifyJwtAndGetClaims(userToken);
            userId = (Long) claims.get(JWTUtilityConstant.CLAIM_USERID);
            codiceFiscale = (String) claims.get(JWTUtilityConstant.CLAIM_USERNAME);


        } catch (JwtException e) {
            throw new ForbiddenException(e.getDescription());
        }

        long companyId;
        try {
            if (Validator.isNotNull(nomeComune)) {
                companyId = _organizationUtility.getByName(nomeComune).getCompanyId();
            } else {
                companyId = _organizationUtility.getByName(amministrazione).getCompanyId();
            }

        } catch (Exception e) {
            throw new BadRequestException("Comune/amministrazione non esistente");
        }


        ComunicazioneFilters comunicazioneFilters = new ComunicazioneFilters();
        mapFilters(filtriComunicazioni, comunicazioneFilters, codiceFiscale, userId, companyId);


        List<ComunicazioneUtenteResponse> listaComunicazioni = getListaComunicazioniScrivaniaCittadino(comunicazioneFilters);
        List<ComunicazioneUtenteResponse> listaCommenti = getCommentiComunicazioneScrivaniaCittadino(comunicazioneFilters, companyId, new Locale("it"));

        List<ComunicazioneUtenteResponse> listaCompleta = new ArrayList<ComunicazioneUtenteResponse>();

        if (listaComunicazioni != null && !listaComunicazioni.isEmpty()) {
            listaCompleta.addAll(listaComunicazioni);
        }

        if (listaCommenti != null && !listaCommenti.isEmpty()) {
            listaCompleta.addAll(listaCommenti);
        }


        if (Validator.isNotNull(comunicazioneFilters)) {
            Stream<ComunicazioneUtenteResponse> listaCompletaStream = listaCompleta.stream();

            if (!Validator.isBlank(comunicazioneFilters.getTitoloDescrizione())) {
                listaCompletaStream = listaCompletaStream.filter(com -> {
                    if (com.getTitolo().toLowerCase().contains(comunicazioneFilters.getTitoloDescrizione().toLowerCase())) {
                        return true;
                    }

                    return false;
                });
            }

            listaCompleta = listaCompletaStream.collect(Collectors.toList());
        }

        // Collections.sort(listaCompleta,
        // Comparator.comparing(ComunicazioneDto::getDataUltimoMessaggio).reversed());

//		if (Validator.isNotNull(listaCompleta) && !listaCompleta.isEmpty()) {
//			for (ComunicazioneDto comunicazioneDto : listaCompleta) {
//				if (Validator.isNotNull(comunicazioneDto)) {
//					TipologiaComunicazione tipologiaComunicazione = TipologiaComunicazione.getByKey(comunicazioneDto.getTipologia());
//					if (tipologiaComunicazione.equals(TipologiaComunicazione.COMUNICAZIONE)) {
//						boolean isLetta = isComunicazioneLetta(comunicazioneDto.getId(), userId);
//						comunicazioneDto.setLetta(isLetta);
//					}
//				}
//			}
//		}

        if (!listaCompleta.isEmpty()) {
            listaCompleta.sort((o1, o2) -> {

                int result = 0;

                if (o1.getDataUltimoMessaggio() != null && o2.getDataUltimoMessaggio() != null) {
                    result = o2.getDataUltimoMessaggio().compareTo(o1.getDataUltimoMessaggio());

                    if (result == 0) {
                        result = o1.getLetta().compareTo(o2.getLetta());
                    }
                } else {
                    if (o1.getDataUltimoMessaggio() != null) {
                        result = -1;
                    }

                    if (o2.getDataUltimoMessaggio() != null) {
                        result = 1;
                    }
                }
                return result;
            });

        }

        if (Validator.isNull(page)) {
            page = 1;
        }
        if (Validator.isNull(size)) {
            size = 10;
        }

        int start = (page - 1) * size;
        int end = Math.min(start + size, listaCompleta.size());

        if (start >= listaCompleta.size() || start < 0) {
            return Page.of(Collections.emptyList(), Pagination.of(page, size), listaCompleta.size());
        }

        List<ComunicazioneUtenteResponse> resultList = listaCompleta.subList(start, end);
        return Page.of(resultList, Pagination.of(page, size), listaCompleta.size());

    }

    private void mapFilters(FiltriComunicazioni filtriComunicazioni, ComunicazioneFilters comunicazioneFilters, String codiceFiscale, Long userId, long companyId) {

        if (filtriComunicazioni.getTitoloDescrizione() != null) {
            comunicazioneFilters.setTitoloDescrizione(filtriComunicazioni.getTitoloDescrizione());
        }
        if (filtriComunicazioni.getOrganizzazione() != null) {
            comunicazioneFilters.setOrganizzazione(filtriComunicazioni.getOrganizzazione());
        }
        if (filtriComunicazioni.getTipologia() != null) {
            comunicazioneFilters.setTipologia(filtriComunicazioni.getTipologia());
        }
        if (filtriComunicazioni.getStato() != null) {
            comunicazioneFilters.setStato(filtriComunicazioni.getStato());
        }
        if (filtriComunicazioni.getDataInvioDa() != null) {
            comunicazioneFilters.setDataInvioDa(filtriComunicazioni.getDataInvioDa());
        }
        if (filtriComunicazioni.getDataInvioA() != null) {
            comunicazioneFilters.setDataInvioA(filtriComunicazioni.getDataInvioA());
        }
        if (filtriComunicazioni.getOrderByCol() != null) {
            comunicazioneFilters.setOrderByCol(filtriComunicazioni.getOrderByCol());
        }
        if (filtriComunicazioni.getOrderByType() != null) {
            comunicazioneFilters.setOrderByType(filtriComunicazioni.getOrderByType());
        }
        if (filtriComunicazioni.getDestinatarioId() != null) {
            comunicazioneFilters.setDestinatarioId(filtriComunicazioni.getDestinatarioId());
        }
        if (filtriComunicazioni.getOrganizzazioniIDs() != null) {
            comunicazioneFilters.setOrganizzazioniIDs(Arrays.asList(filtriComunicazioni.getOrganizzazioniIDs()));
        }
        if(filtriComunicazioni.getRichiestaId()!=null){
            comunicazioneFilters.setRichiestaId(filtriComunicazioni.getRichiestaId());
        }

        if (Validator.isNotNull(codiceFiscale)) {
            comunicazioneFilters.setUsername(codiceFiscale);
        }

        if (userId > 0) {
            comunicazioneFilters.setUserId(userId);
        }

        if (companyId > 0) {
            comunicazioneFilters.setCompanyId(companyId);
        }
    }


    private List<ComunicazioneUtenteResponse> getListaComunicazioniScrivaniaCittadino(ComunicazioneFilters comunicazioneFilters) {
        List<Comunicazione> listaComunicazioni = comunicazioneLocalService.searchComunicazioni(comunicazioneFilters);
        List<ComunicazioneUtenteResponse> listaComunicazioniDto = new ArrayList<ComunicazioneUtenteResponse>();

        //comunicazioni non lette
        if (listaComunicazioni != null && !listaComunicazioni.isEmpty()) {
            for (Comunicazione comunicazione : listaComunicazioni) {
                List<Comunicazione> comunicazioniNonLette = new ArrayList<>();
                if (comunicazione.getSubOrganizationId() > 0) {
                    long[] organizationIds = userLocalService.getOrganizationUserIds(comunicazione.getSubOrganizationId());
                    comunicazioniNonLette = comunicazioneLocalService.findComunicazioniNonLetteByUserIdAndSubOrgIds(comunicazioneFilters.getUserId(), organizationIds);
                } else {
                    comunicazioniNonLette = comunicazioneLocalService.findComunicazioniNonLetteByUserId(comunicazioneFilters.getUserId());
                }
                List<Long> comunicazioniNonLetteIds = new ArrayList<>();
                if (Validator.isNotNull(comunicazioniNonLette) && !comunicazioniNonLette.isEmpty()) {
                    comunicazioniNonLetteIds = comunicazioniNonLette.stream().map(c -> c.getComunicazioneId()).collect(Collectors.toList());
                }
                if (comunicazioniNonLetteIds.isEmpty()) {
                    comunicazione.setLetta(true);
                } else if (Validator.isNotNull(comunicazioniNonLetteIds) && !comunicazioniNonLetteIds.isEmpty()) {
                    for (Long idComunicazione : comunicazioniNonLetteIds) {
                        if (idComunicazione == comunicazione.getComunicazioneId()) {
                            comunicazione.setLetta(false);
                            break;
                        } else {
                            comunicazione.setLetta(true);
                        }

