@Reference
private OrganizationLocalService organizationLocalService;

@Reference
private OrganizationUtility _organizationUtility;


@Override
public Page<RichiestaUtenteConAllegatiResponse> getRichiesteUtente(String userToken, String oggettoNote, String idRichiesta, String stato, Long companyId, String nomeComune, String amministrazione, Integer page, Integer size, String orderByCol, String orderByType) throws Exception {

    if ((Validator.isNull(nomeComune) && Validator.isNull(amministrazione)) || (!Validator.isNull(nomeComune) && !Validator.isNull(amministrazione))) {
        throw new BadRequestException("E' obbligatorio compilare solo uno tra i due campi nomeComune e amministrazione");
    }

    String codiceFiscale;
    try {
        Map<String, Object> claims = _jwtUtilityService.verifyJwtAndGetClaims(userToken);
        codiceFiscale = (String) claims.get(JWTUtilityConstant.CLAIM_USERNAME);

    } catch (JwtException e) {
        throw new ForbiddenException(e.getDescription());
    }

    RichiestaFilters richiestaFilter = new RichiestaFilters();
    richiestaFilter.setCodiceFiscale(codiceFiscale);

    if (Validator.isNotNull(companyId)) {
        richiestaFilter.setCompanyId(companyId);
    }

    if (Validator.isNotNull(companyId)) {
        richiestaFilter.setCompanyId(companyId);
    } else if (Validator.isNotNull(nomeComune)) {
        richiestaFilter.setCompanyId(_organizationUtility.getByName(nomeComune).getCompanyId());
    }else {
        richiestaFilter.setCompanyId( _organizationUtility.getByName(amministrazione).getCompanyId());
    }

    richiestaFilter.setOrderByCol("modifiedDate");
    richiestaFilter.setOrderByType("desc");

    if (Validator.isNotNull(oggettoNote)) {
        richiestaFilter.setOggettoNote(oggettoNote);
    }

    if (Validator.isNotNull(stato)) {
        richiestaFilter.setTipo(stato);
    }

    if (Validator.isNotNull(idRichiesta)) {
        richiestaFilter.setIdRichiesta(idRichiesta);
    }

    if (Validator.isNotNull(orderByCol)) {
        richiestaFilter.setOrderByCol(orderByCol);
    }

    if (Validator.isNotNull(orderByType)) {
        richiestaFilter.setOrderByType(orderByType);
    }

    List<Servizio> serviziNonPagamento = getServiziNonPagamento();

    Set<Long> serviziIds = serviziNonPagamento.stream().map(Servizio::getServizioId).collect(Collectors.toSet());
    richiestaFilter.setServiziIds(serviziIds);

    long elementiTotali = richiestaLocalService.count(richiestaFilter);


    if (Validator.isNull(page)) {
        page = 1;
    }
    if (Validator.isNull(size)) {
        size = 10;
    }

    int[] startEnd = SearchPaginationUtil.calculateStartAndEnd(page, size);
    List<Richiesta> richieste = richiestaLocalService.search(richiestaFilter, startEnd[0], startEnd[1]);
    List<RichiestaUtenteConAllegatiResponse> richiestaAccordionDtos = getRichiesteConAllegati(extractedRichieste(richieste));

    return Page.of(richiestaAccordionDtos, Pagination.of(page, size), elementiTotali);

}

