71			List<User> users;
72			if (DominioEnumDTO.SERVIZIO.equals(dominio)) {
73				List<Richiesta> richieste = richiestaLocalService.getRichiestas(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
74				List<Long> usersId = richieste.stream()
75					.filter(richiesta -> richiesta.getUserName().toLowerCase().contains(query.toLowerCase()) || richiesta.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()))
76					.map(richiesta -> richiesta.getUserId())
77					.distinct()
78					.limit(limit)
79					.collect(Collectors.toList());
80				
81				users = usersId.stream().map(userId -> userLocalService.fetchUser(userId)).collect(Collectors.toList());
82				
83				return users.stream().map(this::mapUser).collect(Collectors.toList());
84			} else {
85				List<DomandaBando> domande = new ArrayList<DomandaBando>();
86				if(codiceStatoDomanda.isEmpty() || codiceStatoDomanda.equals("")) {
87					
88					domande = domandaBandoLocalService.getDomandeBandoByBandoId(itemId)
89							.stream()
90							.filter((domanda) -> domanda.getUserName().toLowerCase().contains(query.toLowerCase()) || 
91												 domanda.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()) ||
92												 domanda.getRagioneSociale().toLowerCase().contains(query.toLowerCase()))
93							.distinct()
94							.limit(limit)
95							.collect(Collectors.toList());	
96					
97					
98				}else {
99					List<DomandaBando> domandeTmp = domandaBandoLocalService.getDomandeBandoByBandoId(itemId)
100							.stream()
101							.filter((domanda) -> domanda.getUserName().toLowerCase().contains(query.toLowerCase()) || 
102												 domanda.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()) ||
103												 domanda.getRagioneSociale().toLowerCase().contains(query.toLowerCase()))
104							
105							.distinct()
106							.limit(limit)
107							.collect(Collectors.toList());	
108					
109					for(DomandaBando domandaBando: domandeTmp) {
110						if(domandaBando.getStatoId() == 0 && domandaBando.getStato().equalsIgnoreCase(codiceStatoDomanda)) 
111							domande.add(domandaBando);
112						else 
113							if(domandaBando.getStatoId() != 0) {
114								String stato = statoDomandaLocalService.fetchStatoDomanda(domandaBando.getStatoId()).getCodice();
