159					if(organizationUser.isPresent() && Validator.isNotNull(organizationUser.get())) {
160						Organization organization = organizationUser.get();
161						
162						if(Validator.isNotNull(organization.getSuborganizations())) {
163							List<Organization> subOrganizationsPadre = organization.getSuborganizations();
164							
165							for(Organization userOrganization : userOrganizations ) {
166								if(Validator.isNotNull(userOrganization)) {
167									if(userOrganization.getOrganizationId() != organization.getOrganizationId()) {
168										Optional<Organization> organizationFound = subOrganizationsPadre.stream().filter(x -> x.getOrganizationId() == userOrganization.getOrganizationId()).findAny();
169										
170										if(organizationFound.isPresent() && Validator.isNotNull(organizationFound)) {
