@Component(immediate = true, service = ComunicazioneFrontendService.class)
public class ComunicazioneFrontendService {

	private static final Log log = LogFactoryUtil.getLog(ComunicazioneFrontendService.class.getName());

	@Reference
	private UserLocalService userLocalService;
	@Reference
	private ServizioLocalService servizioLocalService;
	@Reference
	private RichiestaLocalService richiestaLocalService;
	@Reference
	private BandoLocalService bandoLocalService;
	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;
	@Reference
	private ServizioEnteLocalService servizioEnteLocalService;
	@Reference
	private StatoDomandaLocalService statoDomandaLocalService;

	@Reference
	private OrganizationUtility organizationUtility;
	@Reference
	private GroupLocalService groupLocalService;
	@Reference
	private OrganizationLocalService organizationLocalService;

	public List<UtenteDTO> ricerca(ServiceContext serviceContext, DominioEnumDTO dominio, long itemId, String query, int limit, String codiceStatoDomanda) throws PortalException {
		List<User> users;
		if (DominioEnumDTO.SERVIZIO.equals(dominio)) {
			List<Richiesta> richieste = richiestaLocalService.getRichiestas(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
			List<Long> usersId = richieste.stream()
				.filter(richiesta -> richiesta.getUserName().toLowerCase().contains(query.toLowerCase()) || richiesta.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()))
				.map(richiesta -> richiesta.getUserId())
				.distinct()
				.limit(limit)
				.collect(Collectors.toList());

			users = usersId.stream().map(userId -> userLocalService.fetchUser(userId)).collect(Collectors.toList());

			return users.stream().map(this::mapUser).collect(Collectors.toList());
		} else {
			List<DomandaBando> domande = new ArrayList<DomandaBando>();
			if(codiceStatoDomanda.isEmpty() || codiceStatoDomanda.equals("")) {

				domande = domandaBandoLocalService.getDomandeBandoByBandoId(itemId)
						.stream()
						.filter((domanda) -> domanda.getUserName().toLowerCase().contains(query.toLowerCase()) || 
											 domanda.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()) ||
											 domanda.getRagioneSociale().toLowerCase().contains(query.toLowerCase()))
						.distinct()
						.limit(limit)
						.collect(Collectors.toList());	


			}else {
				List<DomandaBando> domandeTmp = domandaBandoLocalService.getDomandeBandoByBandoId(itemId)
						.stream()
						.filter((domanda) -> domanda.getUserName().toLowerCase().contains(query.toLowerCase()) || 
											 domanda.getCodiceFiscale().toLowerCase().contains(query.toLowerCase()) ||
											 domanda.getRagioneSociale().toLowerCase().contains(query.toLowerCase()))

						.distinct()
						.limit(limit)
						.collect(Collectors.toList());	

				for(DomandaBando domandaBando: domandeTmp) {
					if(domandaBando.getStatoId() == 0 && domandaBando.getStato().equalsIgnoreCase(codiceStatoDomanda)) 
						domande.add(domandaBando);
					else 
						if(domandaBando.getStatoId() != 0) {
							String stato = statoDomandaLocalService.fetchStatoDomanda(domandaBando.getStatoId()).getCodice();
							if(stato.equalsIgnoreCase(codiceStatoDomanda)) 
								domande.add(domandaBando);

					}	
				}

			}
			return domande.stream().map(this::mapUserRagioneSociale).collect(Collectors.toList());
		}

	}

	public List<ServizioDTO> getServizi(long organizationId) {
		DynamicQuery dynamicQuery = servizioEnteLocalService.dynamicQuery();
		dynamicQuery.add(RestrictionsFactoryUtil.eq("primaryKey.organizationId", organizationId));
		dynamicQuery.add(RestrictionsFactoryUtil.eq("attivo", true));
		List<ServizioEnte> serviziEnte = servizioEnteLocalService.<ServizioEnte>dynamicQuery(dynamicQuery);
		List<Long> serviziId = serviziEnte.stream()
				.map(servizioEnte -> servizioEnte.getServizioId())
				.collect(Collectors.toList());
		List<Servizio> servizi = serviziId.stream()
				.map(servizioId -> servizioLocalService.fetchServizio(servizioId))
				.filter(servizio -> servizio.isAttivo())
				.collect(Collectors.toList());
		return servizi.stream().map(this::mapServizio).collect(Collectors.toList());
	}

	public List<BandoDTO> getBandi(ServiceContext serviceContext) throws PortalException {
		List<Long> idSottoOrganizzazioni = getUserSubOrganization(serviceContext.getScopeGroupId(), serviceContext.getUserId());
		List<Bando> bandi = bandoLocalService.getBandiBySubOrganization(idSottoOrganizzazioni, serviceContext.getScopeGroupId(), serviceContext.getCompanyId());
		return bandi.stream().map(this::mapBando).collect(Collectors.toList());
	}

	public List<Long> getUserSubOrganization(long groupId, long userId) throws PortalException {
		User user = userLocalService.getUser(userId);
		List<Long> ids = new ArrayList<Long>();

		if(Validator.isNotNull(user)) {

			if(Validator.isNotNull(user.getOrganizations())) {
				List<Organization> userOrganizations = user.getOrganizations();
				Group siteGroup = groupLocalService.getGroup(groupId);
				Optional<Organization> organizationUser = userOrganizations.stream().filter(x -> x.getOrganizationId() == siteGroup.getOrganizationId()).findAny();

				if(organizationUser.isPresent() && Validator.isNotNull(organizationUser.get())) {
					Organization organization = organizationUser.get();

					if(Validator.isNotNull(organization.getSuborganizations())) {
						List<Organization> subOrganizationsPadre = organization.getSuborganizations();

						for(Organization userOrganization : userOrganizations ) {
							if(Validator.isNotNull(userOrganization)) {
								if(userOrganization.getOrganizationId() != organization.getOrganizationId()) {
									Optional<Organization> organizationFound = subOrganizationsPadre.stream().filter(x -> x.getOrganizationId() == userOrganization.getOrganizationId()).findAny();

									if(organizationFound.isPresent() && Validator.isNotNull(organizationFound)) {
										ids.add(organizationFound.get().getOrganizationId());
									}
								}
							}
						}
					}

				}


			}


		}


		return ids;
	}

	private BandoDTO mapBando(Bando bando) {
		BandoDTO dto = new BandoDTO();
		dto.setId(bando.getBandoId());
		dto.setNome(bando.getNome());
		return dto;
	}

	private UtenteDTO mapUser(User user) {
		UtenteDTO dto = new UtenteDTO();
		dto.setId(user.getUserId());
		dto.setNome(user.getFullName());
		dto.setCf(user.getScreenName().toUpperCase());
		return dto;
	}

	private UtenteDTO mapUserRagioneSociale(DomandaBando domandaBando) {
		UtenteDTO dto = new UtenteDTO();
		User user = userLocalService.fetchUser(domandaBando.getUserId());
		dto.setId(user.getUserId());
		dto.setNome(user.getFullName());
		dto.setCf(user.getScreenName().toUpperCase());
		dto.setRagioneSociale(domandaBando.getRagioneSociale());
		return dto;
	}

	private ServizioDTO mapServizio(Servizio servizio) {
		ServizioDTO dto = new ServizioDTO();
		dto.setCodice(servizio.getCodice());
		dto.setNome(servizio.getNome());
		return dto;
	}

	public List<Organization> getUserOrganizationFromSiteGroup(long siteGroupId, long userId, long companyId) throws PortalException {

		Organization organization = organizationUtility.getSiteOrganization(siteGroupId);
		List<Organization> organizations = new ArrayList<Organization>();
		Group siteGroup = groupLocalService.getGroup(siteGroupId);

		long groupOrganizationId = siteGroup.getOrganizationId();

		if (groupOrganizationId != 0) {
			List<Organization> userOrganizations =  organizationLocalService.getUserOrganizations(userId, true);
			List<Organization> subOrganizations = organizationLocalService.getSuborganizations(companyId, groupOrganizationId);

			if(!subOrganizations.isEmpty() && !userOrganizations.isEmpty()) 
				for(Organization o : subOrganizations) {
					if(userOrganizations.contains(o))
						organizations.add(o);
				}
		}
		else 
			organizations.add(organization);


		return organizations;
	}
}

