import it.servizidigitali.gestionecomunicazioni.frontend.dto.DominioEnumDTO;
import it.servizidigitali.gestionecomunicazioni.frontend.dto.UtenteDTO;
import it.servizidigitali.gestionecomunicazioni.frontend.service.ComunicazioneFrontendService;

@Component(immediate = true, service = MVCResourceCommand.class, property = {
		"javax.portlet.name=" + GestioneComunicazioniFrontendPortletKeys.GESTIONECOMUNICAZIONI,
		"mvc.command.name=/resource/ricercaUtenti"
})
public class RicercaUtentiResourceCommand extends BaseMVCResourceCommand {

	@Reference
	private ComunicazioneFrontendService utenteService;
	@Reference
	private AuditService auditService;
	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;
	@Reference
	private StatoDomandaLocalService statoDomandaLocalService;

	@Override
	protected void doServeResource(ResourceRequest request, ResourceResponse response) throws Exception {
		String query = ParamUtil.getString(request, "query");		
		String codiceStatoDomanda = ParamUtil.getString(request, "statoDomanda");
		int limit = ParamUtil.getInteger(request, "limit");
		DominioEnumDTO dominio = DominioEnumDTO.valueOf(ParamUtil.getString(request, "dominio"));
		long itemId = ParamUtil.getLong(request, "itemId");

		if(query.isEmpty() && limit == 0) {
			//check domandeBando per bandoId = itemId
			try {
				int count = 0;
				if(codiceStatoDomanda.isEmpty() || codiceStatoDomanda.equals("")) {

					count = (int) domandaBandoLocalService.countDomandeBandoById(itemId);
				}else {
					List<DomandaBando> domande = domandaBandoLocalService.getDomandeBandoByBandoId(itemId);
					for(DomandaBando domandaBando : domande) {
						if(domandaBando.getStatoId() == 0 && domandaBando.getStato().equalsIgnoreCase(codiceStatoDomanda)) {
							count++;
						}else
							if(domandaBando.getStatoId() != 0) {
								String stato = statoDomandaLocalService.fetchStatoDomanda(domandaBando.getStatoId()).getCodice();
								if(stato.equalsIgnoreCase(codiceStatoDomanda)) count++;
							}
					}

				}
				ObjectMapper om = new ObjectMapper();

				String payload = om.writeValueAsString(count);
				response.getPortletOutputStream().write(payload.getBytes());
			} catch (Exception e) {
				auditService.saveErrorLog(request, e.getMessage());
				String payload = "{ \"error\": \"generico\" }";
				response.getPortletOutputStream().write(payload.getBytes());
			}


		}else {
			try {
				ServiceContext ctx = ServiceContextFactory.getInstance(request);
				List<UtenteDTO> utenti = utenteService.ricerca(ctx, dominio, itemId, query, limit, codiceStatoDomanda);

				ObjectMapper om = new ObjectMapper();

				String payload = om.writeValueAsString(utenti);
				response.getPortletOutputStream().write(payload.getBytes());
			} catch (Exception e) {
				auditService.saveErrorLog(request, e.getMessage());
				String payload = "{ \"error\": \"generico\" }";
				response.getPortletOutputStream().write(payload.getBytes());
			}
		}


	}

}

