96		@Override
97		public Utente getUtente(@NotNull String userToken, String nomeComune) throws Exception {
98	
99			try {
100				Map<String, Object> claims = _jwtUtilityService.verifyJwtAndGetClaims(userToken);
101				String codiceFiscale = (String) claims.get(JWTUtilityConstant.CLAIM_USERNAME);
102	
103				Organization organization = _organizationUtility.getByName(nomeComune);
104	
105				if (organization == null) {
106					throw new NotFoundException("Ente non trovato");
107				}
108	
109				Group organizationSite = _organizationUtility.getOrganizationSite(organization.getOrganizationId());
110	
111				User user = _userLocalService.fetchUserByScreenName(organizationSite.getCompanyId(), codiceFiscale.toLowerCase());
112	
113				if (user != null) {
114	
115					Utente utente = new Utente();
116					utente.setCodiceFiscale(user.getScreenName().toUpperCase());
117					utente.setCognome(user.getLastName());
118					utente.setDataNascita(user.getBirthday());
119					utente.setEmail(user.getEmailAddress());
120	
