@Component(properties = "OSGI-INF/liferay/rest/v1_0/dati-anagrafici.properties", scope = ServiceScope.PROTOTYPE, service = DatiAnagraficiResource.class)
public class DatiAnagraficiResourceImpl extends BaseDatiAnagraficiResourceImpl {

	@Override
	public Page<ComponenteNucleoFamiliareLight> getComponentiNucleoFamiliare(@NotNull String userToken, String nomeComune) throws Exception {

		try {
			Map<String, Object> claims = _jwtUtilityService.verifyJwtAndGetClaims(userToken);
			String codiceFiscale = (String) claims.get(JWTUtilityConstant.CLAIM_USERNAME);

			Organization organization = _organizationUtility.getByName(nomeComune);

			Group organizationSite = _organizationUtility.getOrganizationSite(organization.getOrganizationId());

			AnagrafeIntegrationService anagrafeIntegrationService = _anagrafeIntegrationFactoryService.getAnagrafeIntegrationService(organizationSite.getGroupId());

			if (anagrafeIntegrationService == null) {
				throw new NotActiveException("Integrazione non abilitata.");
			}

			DatiAnagrafici datiAnagrafici = anagrafeIntegrationService.getDatiAnagrafici(codiceFiscale, null, organization.getOrganizationId(), null);

			List<ComponenteNucleoFamiliareLight> res = new ArrayList<>();
			List<ComponenteNucleoFamiliare> componenti = datiAnagrafici.getComponentiNucleoFamiliare();
			if (componenti != null) {
				componenti.forEach(c -> {
					ComponenteNucleoFamiliareLight l = new ComponenteNucleoFamiliareLight();
					l.setCodiceFiscale(c.getCodiceFiscale());
					l.setCognome(c.getCognome());
					l.setDataNascita(c.getDataNascita());
					l.setNome(c.getNome());
					l.setSesso(c.getSesso());

					res.add(l);
				});
			}
			else {
				throw new NotFoundException("Lista componenti nucleo familiare vuota");
			}

			Page<ComponenteNucleoFamiliareLight> page = Page.of(res);

			return page;
		}
		catch (JwtException e) {
			throw new ForbiddenException(e.getDescription());
		}
	}

	@Override
	public Utente getUtente(@NotNull String userToken, String nomeComune) throws Exception {

		try {
			Map<String, Object> claims = _jwtUtilityService.verifyJwtAndGetClaims(userToken);
			String codiceFiscale = (String) claims.get(JWTUtilityConstant.CLAIM_USERNAME);

			Organization organization = _organizationUtility.getByName(nomeComune);

			if (organization == null) {
				throw new NotFoundException("Ente non trovato");
			}

			Group organizationSite = _organizationUtility.getOrganizationSite(organization.getOrganizationId());

			User user = _userLocalService.fetchUserByScreenName(organizationSite.getCompanyId(), codiceFiscale.toLowerCase());

			if (user != null) {

				Utente utente = new Utente();
				utente.setCodiceFiscale(user.getScreenName().toUpperCase());
				utente.setCognome(user.getLastName());
				utente.setDataNascita(user.getBirthday());
				utente.setEmail(user.getEmailAddress());

				Serializable emailAggiuntiva = getUserExpandoValue(user, UserCustomAttributes.EMAIL_AGGIUNTIVA.getNomeAttributo());
				if (emailAggiuntiva != null && !emailAggiuntiva.toString().isEmpty()) {
					utente.setEmail(emailAggiuntiva.toString());
				}
